/**
 * GENERATED, do not edit by hand. Simplified outlines of Africa's countries as SVG paths, from
 * Natural Earth 1:50m (public domain) via world-atlas. Regenerate with the map script in the
 * project notes if the outlines ever need changing.
 */
export const AFRICA_VIEWBOX = { width: 800, height: 860 };

/** Mercator parameters matching the paths, so [longitude, latitude] can be placed on the map. */
const SCALE = 622.6669;
const TX = 215.7944;
const TY = 446.8262;

export function projectToAfrica([lng, lat]: [number, number]): [number, number] {
  const lambda = (lng * Math.PI) / 180;
  const phi = (lat * Math.PI) / 180;
  return [SCALE * lambda + TX, TY - SCALE * Math.log(Math.tan(Math.PI / 4 + phi / 2))];
}

